const h = await history();
const bugs = h.items.filter(i => (i.kind||'').toLowerCase()==='bug');
const states = {}; bugs.forEach(b=>{states[b.state]=(states[b.state]||0)+1});
const kinds={}; h.items.forEach(i=>{kinds[i.kind]=(kinds[i.kind]||0)+1});
return {asOf:h.asOf, since:h.since, total:h.items.length, kinds, states, inprog: bugs.filter(b=>b.startedAt && !b.doneAt).map(b=>({id:b.id,state:b.state,days:b.daysInState,startedAt:b.startedAt,assignee:b.assignee}))};

const h = await history();
const bugs = h.items.filter(i => (i.kind||'').toLowerCase()==='bug');
const states: Record<string,number> = {}; bugs.forEach(b=>{const k=String(b.state);states[k]=(states[k]||0)+1});
const kinds: Record<string,number>={}; h.items.forEach(i=>{const k=String(i.kind);kinds[k]=(kinds[k]||0)+1});
return {asOf:h.asOf, since:h.since, total:h.items.length, kinds, states, inprog: bugs.filter(b=>b.startedAt && !b.doneAt).map(b=>({id:b.id,state:b.state,days:b.daysInState,startedAt:b.startedAt,assignee:b.assignee}))};

